1	package custody
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"os"
7		"path/filepath"
8		"sort"
9		"strings"
10		"sync"
11		"time"
12	)
13	
14	// Store 是一份本地样品数据的入口。零值不可用，请通过 Open 创建或重新打开。
15	//
16	// 同一时刻所有读写操作都由一把互斥锁串行化，因此并发操作同一样品时，
17	// 既不会超量分装，也不会出现两条待确认交接。每次成功的写操作都会
18	// 原子落盘（临时文件 + rename），关闭后重新打开同一文件即可恢复
19	// 全部样品、保管历史以及交接编号的重复提交判断。
20	type Store struct {
21		path string
22		mu   sync.Mutex
23		data *ledger
24	
25		// now 可在同包测试中替换，便于确定性地控制事件时间。
26		now func() time.Time
27	}
28	
29	// Open 打开 path 指向的本地样品数据：文件不存在时创建一份新数据，
30	// 已存在时原样重新打开，历史记录与交接编号判断继续有效。
31	func Open(path string) (*Store, error) {
32		if strings.TrimSpace(path) == "" {
33			return nil, fmt.Errorf("%w: 数据文件路径不能为空", ErrInvalid)
34		}
35	
36		s := &Store{path: path, now: time.Now}
37	
38		raw, err := os.ReadFile(path)
39		switch {
40		case err == nil:
41			var l ledger
42			if err := json.Unmarshal(raw, &l); err != nil {
43				return nil, fmt.Errorf("读取本地样品数据 %s 失败: %w", path, err)
44			}
45			if l.Version != 1 {
46				return nil, fmt.Errorf("本地样品数据 %s 的版本 %d 不受支持", path, l.Version)
47			}
48			if l.Samples == nil {
49				l.Samples = make(map[string]*sampleRecord)
50			}
51			if l.Transfers == nil {
52				l.Transfers = make(map[string]*transferRecord)
53			}
54			if err := validateRestored(&l); err != nil {
55				return nil, err
56			}
57			s.data = &l
58		case os.IsNotExist(err):
59			s.data = newLedger()
60			if err := s.persist(s.data); err != nil {
61				return nil, err
62			}
63		default:
64			return nil, fmt.Errorf("打开本地样品数据 %s 失败: %w", path, err)
65		}
66		return s, nil
67	}
68	
69	// validateRestored 校验从文件恢复的数据中交接关联是否一致。
70	// 样品的非空 pendingId 必须指向一条实际存在、尚未确认、且属于该样品的
71	// 交接；每条尚未确认的交接也必须对应一份实际存在、且 pendingId 正好指向
72	// 它的样品。待确认交接表示样品当前全部剩余量尚待指定人员接收，因此其
73	// 内容还必须与样品当前记录一致：样品未销毁、剩余量大于零、交出人等于
74	// 当前持有人、交出地点等于当前地点、交接量精确等于当前剩余量。
75	//
76	// 已确认交接属于保留的历史，不要求样品继续指向它，也不核对其与样品当前
77	// 持有人、地点或剩余量的差异（样品后来分装、移动或销毁都不能否定当时的
78	// 接收事实）；但它必须保留有效的接收信息：确认人非空且与该交接原先指定
79	// 的接收人一致，接收时间存在且非零，且按实际时刻不早于交出时间（恰好
80	// 相等合法，时区只影响表示）。集合中占用编号却为 null 的条目视为损坏，
81	// 不能当作记录不存在。任一问题都使整个文件无法恢复，绝不只加载其中
82	// 一部分，也不改动原文件。
83	func validateRestored(l *ledger) error {
84		sampleIDs := make([]string, 0, len(l.Samples))
85		for id := range l.Samples {
86			sampleIDs = append(sampleIDs, id)
87		}
88		sort.Strings(sampleIDs)
89		for _, id := range sampleIDs {
90			rec := l.Samples[id]
91			if rec == nil {
92				return fmt.Errorf("%w: 样品编号 %q 已被占用但记录为 null，无法恢复", ErrInvalid, id)
93			}
94			if rec.PendingID == "" {
95				continue
96			}
97			tr, ok := l.Transfers[rec.PendingID]
98			switch {
99			case !ok:
100				return fmt.Errorf("%w: 样品 %q 记着待确认交接 %q，但该交接不存在，无法恢复",
101					ErrInvalid, id, rec.PendingID)
102			case tr == nil:
103				return fmt.Errorf("%w: 样品 %q 记着待确认交接 %q，但该交接记录为 null，无法恢复",
104					ErrInvalid, id, rec.PendingID)
105			case tr.Confirmed:
106				return fmt.Errorf("%w: 样品 %q 记着的交接 %q 已确认，不能仍是待确认，无法恢复",
107					ErrInvalid, id, rec.PendingID)
108			case tr.SampleID != id:
109				return fmt.Errorf("%w: 样品 %q 记着的待确认交接 %q 属于样品 %q，无法恢复",
110					ErrInvalid, id, rec.PendingID, tr.SampleID)
111			}
112			if err := validatePendingContent(id, rec, tr); err != nil {
113				return err
114			}
115		}
116	
117		transferIDs := make([]string, 0, len(l.Transfers))
118		for id := range l.Transfers {
119			transferIDs = append(transferIDs, id)
120		}
121		sort.Strings(transferIDs)
122		for _, id := range transferIDs {
123			rec := l.Transfers[id]
124			if rec == nil {
125				return fmt.Errorf("%w: 交接编号 %q 已被占用但记录为 null，无法恢复", ErrInvalid, id)
126			}
127			if rec.Confirmed {
128				if err := validateConfirmedReceipt(rec); err != nil {
129					return err
130				}
131				continue
132			}
133			sample, ok := l.Samples[rec.SampleID]
134			switch {
135			case !ok:
136				return fmt.Errorf("%w: 待确认交接 %q 对应的样品 %q 不存在，无法恢复",
137					ErrInvalid, id, rec.SampleID)
138			case sample == nil:
139				return fmt.Errorf("%w: 待确认交接 %q 对应的样品 %q 记录为 null，无法恢复",
140					ErrInvalid, id, rec.SampleID)
141			case sample.PendingID != id:
142				return fmt.Errorf("%w: 待确认交接 %q 的样品 %q 并未记着该交接编号，无法恢复",
143					ErrInvalid, id, rec.SampleID)
144			default:
145				if err := validatePendingContent(rec.SampleID, sample, rec); err != nil {
146					return err
147				}
148			}
149		}
150		return nil
151	}
152	
153	// validatePendingContent 核对一条待确认交接的内容是否与样品当前记录一致。
154	// 待确认交接表示样品当前全部剩余量尚待指定人员接收：样品必须未销毁且
155	// 剩余量大于零，交接的交出人、交出地点和交接量必须分别精确等于样品的
156	// 当前持有人、当前地点和当前剩余量。任一不符都返回包装了 ErrInvalid 的
157	// 错误，并在信息中写明样品编号、交接编号以及冲突项（人员、地点、数量
158	// 或销毁状态）；数量冲突同时列出双方数量，统一按三位小数毫升展示。
159	func validatePendingContent(sampleID string, sample *sampleRecord, tr *transferRecord) error {
160		switch {
161		case sample.Destroyed != nil:
162			return fmt.Errorf("%w: 样品 %q 的待确认交接 %q 仍存在，但样品已销毁，无法恢复",
163				ErrInvalid, sampleID, tr.ID)
164		case sample.Remaining <= 0:
165			return fmt.Errorf("%w: 样品 %q 的待确认交接 %q 仍存在，但样品当前剩余量为 %s 毫升（未销毁），无法恢复",
166				ErrInvalid, sampleID, tr.ID, formatUnits(sample.Remaining))
167		case tr.FromHolder != sample.Holder:
168			return fmt.Errorf("%w: 样品 %q 的待确认交接 %q 的交出人 %q 与样品当前持有人 %q 不一致，无法恢复",
169				ErrInvalid, sampleID, tr.ID, tr.FromHolder, sample.Holder)
170		case tr.FromLocation != sample.Location:
171			return fmt.Errorf("%w: 样品 %q 的待确认交接 %q 的交出地点 %q 与样品当前地点 %q 不一致，无法恢复",
172				ErrInvalid, sampleID, tr.ID, tr.FromLocation, sample.Location)
173		case tr.Qty != sample.Remaining:
174			return fmt.Errorf("%w: 样品 %q 的待确认交接 %q 的交接量 %s 毫升与样品当前剩余量 %s 毫升不一致，无法恢复",
175				ErrInvalid, sampleID, tr.ID, formatUnits(tr.Qty), formatUnits(sample.Remaining))
176		}
177		return nil
178	}
179	
180	// validateConfirmedReceipt 核对一条已确认交接是否保留了有效的接收事实。
181	// 已确认表示样品确实完成过一次转手，因此确认人必须非空（去首尾空白后）
182	// 且与该交接原先指定的接收人完全一致，接收时间必须存在且不是零时间，
183	// 并按实际时刻不早于交出时间（恰好相等合法；不同时区表示同一时刻也算
184	// 相等，时间倒置用 Before 判断而非比较时区偏移后的字面值）。任一不符
185	// 都返回包装了 ErrInvalid 的错误，信息写明交接编号、关联样品编号以及
186	// 具体问题（缺少/空白确认人、确认人不符、缺少或零值接收时间、时间倒置），
187	// 绝不靠补写确认人、猜测接收时间或改回待确认来接受异常记录。
188	func validateConfirmedReceipt(tr *transferRecord) error {
189		switch {
190		case tr.ConfirmedBy == "":
191			return fmt.Errorf("%w: 已确认交接 %q（样品 %q）缺少确认人，无法恢复",
192				ErrInvalid, tr.ID, tr.SampleID)
193		case strings.TrimSpace(tr.ConfirmedBy) == "":
194			return fmt.Errorf("%w: 已确认交接 %q（样品 %q）的确认人不能只有空白，无法恢复",
195				ErrInvalid, tr.ID, tr.SampleID)
196		case tr.ConfirmedBy != tr.ToHolder:
197			return fmt.Errorf("%w: 已确认交接 %q（样品 %q）的确认人 %q 与原定接收人 %q 不一致，无法恢复",
198				ErrInvalid, tr.ID, tr.SampleID, tr.ConfirmedBy, tr.ToHolder)
199		}
200		switch {
201		case tr.ReceivedAt == nil:
202			return fmt.Errorf("%w: 已确认交接 %q（样品 %q）缺少接收时间，无法恢复",
203				ErrInvalid, tr.ID, tr.SampleID)
204		case tr.ReceivedAt.IsZero():
205			return fmt.Errorf("%w: 已确认交接 %q（样品 %q）的接收时间为零值，无法恢复",
206				ErrInvalid, tr.ID, tr.SampleID)
207		case tr.ReceivedAt.Before(tr.HandedOverAt):
208			return fmt.Errorf("%w: 已确认交接 %q（样品 %q）的接收时间 %s 早于交出时间 %s，无法恢复",
209				ErrInvalid, tr.ID, tr.SampleID,
210				tr.ReceivedAt.Format(time.RFC3339), tr.HandedOverAt.Format(time.RFC3339))
211		}
212		return nil
213	}
214	
215	// persist 把整份状态原子写入文件：先写同目录临时文件，再 rename 覆盖，
216	// 避免进程中断留下半截数据。
217	func (s *Store) persist(l *ledger) error {
218		raw, err := json.MarshalIndent(l, "", "  ")
219		if err != nil {
220			return fmt.Errorf("编码本地样品数据失败: %w", err)
221		}
222	
223		dir := filepath.Dir(s.path)
224		tmp, err := os.CreateTemp(dir, ".custody-*.tmp")
225		if err != nil {
226			return fmt.Errorf("创建临时数据文件失败: %w", err)
227		}
228		tmpName := tmp.Name()
229		defer os.Remove(tmpName)
230	
231		if _, err := tmp.Write(raw); err != nil {
232			tmp.Close()
233			return fmt.Errorf("写入临时数据文件失败: %w", err)
234		}
235		if err := tmp.Close(); err != nil {
236			return fmt.Errorf("关闭临时数据文件失败: %w", err)
237		}
238		if err := os.Rename(tmpName, s.path); err != nil {
239			return fmt.Errorf("替换本地样品数据文件失败: %w", err)
240		}
241		return nil
242	}
243	
244	// commit 在候选状态上落盘并替换内存状态。调用方必须保证 candidate
245	// 已通过全部校验；落盘失败时内存状态保持不变。
246	func (s *Store) commit(candidate *ledger) error {
247		if err := s.persist(candidate); err != nil {
248			return err
249		}
250		s.data = candidate
251		return nil
252	}
253	
254	// RegisterInput 是登记原样的入参。
255	type RegisterInput struct {
256		// ID 为样品编号，在这份数据内唯一，去空白后非空。
257		ID string
258		// Qty 为初始数量（毫升），大于零、最多三位小数的十进制字符串。
259		Qty string
260		// Holder 为初始持有人，去空白后非空。
261		Holder string
262		// Location 为初始地点，去空白后非空。
263		Location string
264	}
