662	// DestroyInput 是销毁样品全部剩余量的入参；销毁不接受部分销毁。
663	type DestroyInput struct {
664		// SampleID 为样品编号。
665		SampleID string
666		// Operator 为操作人，去空白后必须与样品当前持有人一致。
667		Operator string
668		// Location 为销毁所在地点，去空白后必须与样品当前地点一致。
669		Location string
670		// At 为销毁时间，不能为零，也不能早于该样品任何已有保管历史的时间。
671		At time.Time
672		// Reason 为销毁原因，去空白后非空。
673		Reason string
674	}
675	
676	// Destroy 销毁该编号样品当时的全部剩余量（不接受部分销毁）。成功后
677	// 剩余量变为 0.000，初始量、来源关系、子样列表与原有保管历史保留，
678	// 持有人和地点保留为销毁前的最后记录，并在保管历史末尾追加一次销毁
679	// 事件；返回该样品的最新查询结果。
680	//
681	// 已销毁样品重复提交完全相同的操作人、地点、时间和原因时，返回原销毁
682	// 结果且不再追加历史；文本按去首尾空白后的内容比较，时间按实际时刻
683	// 比较。任一项不同则返回 ErrConflict，不覆盖原记录。
684	func (s *Store) Destroy(in DestroyInput) (*Sample, error) {
685		s.mu.Lock()
686		defer s.mu.Unlock()
687	
688		sampleID, err := trimRequired("样品编号", in.SampleID)
689		if err != nil {
690			return nil, err
691		}
692		operator, err := trimRequired("操作人", in.Operator)
693		if err != nil {
694			return nil, err
695		}
696		location, err := trimRequired("所在地点", in.Location)
697		if err != nil {
698			return nil, err
699		}
700		reason, err := trimRequired("销毁原因", in.Reason)
701		if err != nil {
702			return nil, err
703		}
704		if in.At.IsZero() {
705			return nil, fmt.Errorf("%w: 销毁时间不能为空", ErrInvalid)
706		}
707		at := in.At.UTC()
708	
709		rec, ok := s.data.Samples[sampleID]
710		if !ok {
711			return nil, fmt.Errorf("%w: 样品 %q 不存在", ErrNotFound, sampleID)
712		}
713	
714		// 已销毁：只接受与首次销毁完全相同的重复提交，原样返回且不再追加历史。
715		if rec.Destroyed != nil {
716			if !sameDestruction(rec.Destroyed, operator, location, at, reason) {
717				return nil, fmt.Errorf("%w: 样品 %q 已销毁，本次销毁信息与原销毁记录不一致",
718					ErrConflict, sampleID)
719			}
720			return buildSampleView(rec, s.data), nil
721		}
722	
723		// 未销毁样品的状态冲突（持有人/地点不匹配按入参语义归入冲突类）。
724		if operator != rec.Holder {
725			return nil, fmt.Errorf("%w: 操作人 %q 与样品 %q 当前持有人 %q 不一致",
726				ErrConflict, operator, sampleID, rec.Holder)
727		}
728		if location != rec.Location {
729			return nil, fmt.Errorf("%w: 销毁地点 %q 与样品 %q 当前地点 %q 不一致",
730				ErrConflict, location, sampleID, rec.Location)
731		}
732		if rec.PendingID != "" {
733			return nil, fmt.Errorf("%w: 样品 %q 存在待确认交接 %s，不能销毁",
734				ErrConflict, sampleID, rec.PendingID)
735		}
736		if rec.Remaining == 0 {
737			return nil, fmt.Errorf("%w: 样品 %q 剩余量已为零且未销毁，不能再销毁",
738				ErrConflict, sampleID)
739		}
740		for _, h := range rec.History {
741			if at.Before(h.Time) {
742				return nil, fmt.Errorf("%w: 销毁时间不能早于样品 %q 已有保管历史的时间 %s",
743					ErrInvalid, sampleID, h.Time.Format(time.RFC3339))
744			}
745		}
746	
747		candidate := s.data.deepCopy()
748		cp := candidate.Samples[sampleID]
749		destroyedQty := cp.Remaining
750		cp.Remaining = 0
751		cp.Destroyed = &destructionRecord{
752			Operator: operator,
753			Location: location,
754			At:       at,
755			Reason:   reason,
756			Qty:      destroyedQty,
757		}
758		// 持有人和地点保留为销毁前的最后记录，仅在历史末尾追加销毁事件。
759		cp.History = append(cp.History, historyRecord{
760			Kind:     "destroy",
761			Time:     at,
762			Holder:   operator,
763			Location: location,
764			Detail:   fmt.Sprintf("销毁全部剩余量 %s 毫升，原因：%s", formatUnits(destroyedQty), reason),
765		})
766	
767		if err := s.commit(candidate); err != nil {
768			return nil, err
769		}
770		return buildSampleView(cp, candidate), nil
771	}
772	
773	// sameDestruction 判断本次销毁请求与已有销毁记录是否完全相同。
774	// 文本字段均已去首尾空白，时间按实际时刻（Equal）比较。
775	func sameDestruction(d *destructionRecord, operator, location string, at time.Time, reason string) bool {
776		return d.Operator == operator &&
777			d.Location == location &&
778			d.At.Equal(at) &&
779			d.Reason == reason
780	}
781	
782	// GetSample 按样品编号查询：返回来源关系、初始量/剩余量、当前持有人和
783	// 地点、直接子样、按发生顺序排列的保管历史，以及待确认交接详情。
784	// 样品不存在时返回包装了 ErrNotFound 的错误，不会创建任何记录。
785	func (s *Store) GetSample(id string) (*Sample, error) {
786		s.mu.Lock()
787		defer s.mu.Unlock()
788	
789		sampleID, err := trimRequired("样品编号", id)
790		if err != nil {
791			return nil, err
792		}
793		rec, ok := s.data.Samples[sampleID]
794		if !ok {
795			return nil, fmt.Errorf("%w: 样品 %q 不存在", ErrNotFound, sampleID)
796		}
797		return buildSampleView(rec, s.data), nil
798	}
799	
800	// GetTransfer 按交接编号查询交接详情（待确认或已确认）。
801	// 交接不存在时返回包装了 ErrNotFound 的错误，不会创建任何记录。
802	func (s *Store) GetTransfer(id string) (*TransferView, error) {
803		s.mu.Lock()
804		defer s.mu.Unlock()
805	
806		transferID, err := trimRequired("交接编号", id)
807		if err != nil {
808			return nil, err
809		}
810		rec, ok := s.data.Transfers[transferID]
811		if !ok {
812			return nil, fmt.Errorf("%w: 交接 %q 不存在", ErrNotFound, transferID)
813		}
814		return buildTransferView(rec), nil
815	}
816	
817	// buildSampleView 把内部样品记录转换为对外视图，数量统一格式化为三位小数。
818	func buildSampleView(r *sampleRecord, l *ledger) *Sample {
819		children := append([]string{}, r.Children...)
820		history := make([]History, 0, len(r.History))
821		for _, h := range r.History {
822			history = append(history, History{
823				Kind:     h.Kind,
824				Time:     h.Time,
825				Holder:   h.Holder,
826				Location: h.Location,
827				Detail:   h.Detail,
828			})
829		}
830		v := &Sample{
831			ID:         r.ID,
832			ParentID:   r.ParentID,
833			InitialQty: formatUnits(r.Initial),
834			Remaining:  formatUnits(r.Remaining),
835			Holder:     r.Holder,
836			Location:   r.Location,
837			Children:   children,
838			History:    history,
839		}
840		if r.PendingID != "" {
841			if t, ok := l.Transfers[r.PendingID]; ok {
842				v.PendingTransfer = buildTransferView(t)
843			}
844		}
845		if r.Destroyed != nil {
846			v.Destruction = &Destruction{
847				Operator: r.Destroyed.Operator,
848				Location: r.Destroyed.Location,
849				At:       r.Destroyed.At,
850				Reason:   r.Destroyed.Reason,
851				Qty:      formatUnits(r.Destroyed.Qty),
852			}
853		}
854		return v
855	}
856	
857	// buildTransferView 把内部交接记录转换为对外视图。
858	func buildTransferView(r *transferRecord) *TransferView {
859		v := &TransferView{
860			TransferID:   r.ID,
861			SampleID:     r.SampleID,
862			FromHolder:   r.FromHolder,
863			FromLocation: r.FromLocation,
864			ToHolder:     r.ToHolder,
865			ToLocation:   r.ToLocation,
866			Qty:          formatUnits(r.Qty),
867			HandedOverAt: r.HandedOverAt,
868			Confirmed:    r.Confirmed,
869			ConfirmedBy:  r.ConfirmedBy,
870		}
871		if r.ReceivedAt != nil {
872			rx := *r.ReceivedAt
873			v.ReceivedAt = &rx
874			v.ConfirmedAt = r.ToLocation
875		}
876		return v
877	}
878

